/* Zeiterfassung – Neuaufbau ohne externe Laufzeit-Abhängigkeiten. */
(() => {
  'use strict';

  const config = window.WORKTIME_CONFIG || {};
  const endpoint = String(config.supabaseUrl || '').replace(/\/$/, '');
  const publishableKey = String(config.supabasePublishableKey || '');
  const root = document.getElementById('app');
  const storageKey = 'zeiterfassung-session-v700';
  const today = () => new Date().toISOString().slice(0, 10);
  const state = {
    session: null, profile: null, people: [], view: 'home', date: today(), month: today().slice(0, 7),
    businessId: '', employeeId: '', folder: 'all', selectedCustomerId: '', busy: false, menuOpen: false, notice: { message: '', error: false },
    rows: { entries: [], orders: [], orderItems: [], documents: [], customers: [], days: [], vacations: [], messages: [], materials: [], appointments: [], payslips: [] }
  };

  const esc = value => String(value ?? '').replace(/[&<>'"]/g, char => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', "'": '&#39;', '"': '&quot;' })[char]);
  const number = value => Number(value || 0);
  const hours = value => `${number(value).toLocaleString('de-DE', { minimumFractionDigits: 2, maximumFractionDigits: 2 })} h`;
  const time = value => value ? `${String(value).slice(0, 5)} Uhr` : '—';
  const dateLabel = value => value ? new Intl.DateTimeFormat('de-DE', { day: '2-digit', month: 'long', year: 'numeric' }).format(new Date(`${value}T12:00:00`)) : '';
  const monthLabel = value => new Intl.DateTimeFormat('de-DE', { month: 'long', year: 'numeric' }).format(new Date(`${value}-01T12:00:00`));
  const same = (a, b) => String(a || '') === String(b || '');
  const lower = value => String(value || '').trim().toLocaleLowerCase('de-DE');
  const isManager = () => ['administrator', 'business'].includes(state.profile?.role);
  const isAdmin = () => state.profile?.role === 'administrator';
  const isBusiness = () => state.profile?.role === 'business';
  const allowed = key => isManager() || state.profile?.menu_permissions?.[key] !== false;

  function announce(message, error = false) {
    state.notice = { message: message || '', error };
    const element = document.getElementById('notice');
    if (element) { element.textContent = message || ''; element.className = error ? 'notice error' : 'notice'; }
  }
  const noticeView = () => `<div id="notice" class="${state.notice.error ? 'notice error' : 'notice'}">${esc(state.notice.message)}</div>`;

  function safeJson(text) { try { return text ? JSON.parse(text) : null; } catch { return null; } }
  async function request(path, options = {}) {
    const headers = { apikey: publishableKey, ...(options.headers || {}) };
    if (state.session?.access_token) headers.Authorization = `Bearer ${state.session.access_token}`;
    if (options.body && !(options.body instanceof Blob) && !(options.body instanceof FormData)) headers['Content-Type'] = 'application/json';
    const response = await fetch(`${endpoint}${path}`, { method: options.method || 'GET', headers, body: options.body && !(options.body instanceof Blob) && !(options.body instanceof FormData) ? JSON.stringify(options.body) : options.body });
    const text = await response.text();
    const body = safeJson(text);
    if (!response.ok) throw new Error(body?.message || body?.error_description || body?.error || 'Die Anfrage konnte nicht ausgeführt werden.');
    return body;
  }
  const rest = (path, options) => request(`/rest/v1/${path}`, options);
  const functions = (name, body) => request(`/functions/v1/${name}`, { method: 'POST', body });
  const rows = (table, query = 'select=*') => rest(`${table}?${query}`);
  const write = (table, data, method = 'POST', query = '') => rest(`${table}${query ? `?${query}` : ''}`, { method, body: data, headers: { Prefer: 'return=representation' } });

  async function refreshSession() {
    if (!state.session?.refresh_token) return false;
    try {
      const data = await request('/auth/v1/token?grant_type=refresh_token', { method: 'POST', headers: { Authorization: undefined }, body: { refresh_token: state.session.refresh_token } });
      state.session = data; localStorage.setItem(storageKey, JSON.stringify(data)); return true;
    } catch { return false; }
  }
  async function login(username, password) {
    const name = String(username || '').trim();
    if (!/^[A-Za-z0-9._-]{3,40}$/.test(name)) throw new Error('Bitte einen gültigen Benutzernamen eingeben.');
    const data = await request('/auth/v1/token?grant_type=password', { method: 'POST', headers: { Authorization: undefined }, body: { email: `${name.toLowerCase()}@arbeitszeit.local`, password } });
    state.session = data; localStorage.setItem(storageKey, JSON.stringify(data));
    const loaded = await loadApplication();
    if (!loaded) throw new Error(state.notice.message || 'Die Anmeldung konnte nicht abgeschlossen werden.');
  }
  async function logout() { state.session = null; state.profile = null; localStorage.removeItem(storageKey); render(); }

  function businessList() { return state.people.filter(person => person.role === 'business'); }
  function activeBusinessId() {
    if (isAdmin()) return state.businessId || businessList()[0]?.id || '';
    if (isBusiness()) return state.profile.id;
    return state.profile?.business_id || '';
  }
  function employees() {
    if (!state.profile) return [];
    if (state.profile.role === 'employee') return [state.profile];
    const business = activeBusinessId();
    const people = state.people.filter(person => person.role === 'employee' && same(person.business_id, business));
    return people.length ? people : [state.profile];
  }
  function selectedEmployee() { return employees().find(person => same(person.id, state.employeeId)) || employees()[0] || state.profile; }
  function currentEmployeeId() { return selectedEmployee()?.id || state.profile?.id || ''; }
  function currentBusiness() { return businessList().find(person => same(person.id, activeBusinessId())) || (isBusiness() ? state.profile : null); }

  async function loadApplication() {
    if (!state.session?.access_token) return render();
    state.busy = true; render();
    try {
      const profileRows = await rows('profiles', `id=eq.${encodeURIComponent(state.session.user.id)}&select=*`);
      state.profile = profileRows?.[0] || null;
      if (!state.profile) throw new Error('Dieses Konto ist nicht eingerichtet.');
      await reloadData();
      return true;
    } catch (error) {
      localStorage.removeItem(storageKey); state.session = null; state.profile = null;
      render(); announce(error.message || 'Die Anmeldung konnte nicht vorbereitet werden.', true);
      return false;
    } finally { state.busy = false; render(); }
  }
  async function reloadData() {
    const load = async (name, table, query = 'select=*') => {
      try { state.rows[name] = await rows(table, query) || []; } catch { state.rows[name] = []; }
    };
    await Promise.all([
      load('people', 'profiles', 'select=*'), load('entries', 'time_entries', 'select=*&order=work_date.desc,created_at.desc'),
      load('orders', 'work_orders', 'select=*&order=work_date.desc,created_at.desc'), load('orderItems', 'work_order_items', 'select=*'),
      load('documents', 'work_order_documents', 'select=*'), load('customers', 'customers', 'select=*&order=name.asc'),
      load('days', 'work_days', 'select=*'), load('vacations', 'vacation_requests', 'select=*&order=created_at.desc'),
      load('messages', 'mailbox_messages', 'select=*&order=created_at.desc'), load('materials', 'materials', 'select=*&order=name.asc'),
      load('appointments', 'appointments', 'select=*&order=event_date.asc'), load('payslips', 'employee_payslips', 'select=*&order=created_at.desc')
    ]);
    state.people = state.rows.people;
    const rememberedBusiness = localStorage.getItem('zeiterfassung-business-v700');
    const rememberedEmployee = localStorage.getItem('zeiterfassung-employee-v700');
    if (isAdmin() && businessList().some(person => same(person.id, rememberedBusiness))) state.businessId = rememberedBusiness;
    if (!state.businessId && isAdmin()) state.businessId = businessList()[0]?.id || '';
    if (employees().some(person => same(person.id, rememberedEmployee))) state.employeeId = rememberedEmployee;
    if (!state.employeeId || !employees().some(person => same(person.id, state.employeeId))) state.employeeId = employees()[0]?.id || state.profile.id;
  }
  const run = async (message, job) => {
    state.busy = true; render();
    try { await job(); await reloadData(); announce(message); }
    catch (error) {
      // A request may have succeeded immediately before an optional later step
      // (such as an upload) failed. Keep the screen in sync with saved data.
      try { await reloadData(); } catch { /* retain the original failure */ }
      announce(error.message || 'Die Aktion konnte nicht ausgeführt werden.', true);
    }
    finally { state.busy = false; render(); }
  };

  function loginView() {
    return `<main class="login-page"><section class="login-card"><div class="brand-mark">ZE</div><h1>Zeiterfassung</h1><p>Arbeitszeiten einfach und sicher erfassen.</p><form id="login-form"><label>Firma<input name="company" autocomplete="organization" placeholder="Firmenname"></label><label>Benutzername<input name="username" autocomplete="username" required></label><label>Passwort<input name="password" type="password" autocomplete="current-password" required></label><button class="primary" ${state.busy ? 'disabled' : ''}>Anmelden</button></form><button class="link-button" data-action="forgot">Passwort vergessen?</button>${noticeView()}</section></main>`;
  }
  function navItems() {
    const list = [['home', 'Übersicht', true], ['time', 'Zeiterfassung', allowed('time')], ['orders', 'Arbeitsscheine', allowed('orders')], ['calendar', 'Kalender', allowed('calendar')], ['customers', 'Kunden', allowed('customers')], ['mailbox', 'Postfach', true], ['materials', 'Materialliste', isManager()], ['invoices', 'Abrechnungen Kunden', isManager()], ['settings', 'Einstellungen', true]];
    return list.filter(([, , visible]) => visible).map(([id, title]) => `<button data-action="nav" data-view="${id}" class="${state.view === id ? 'active' : ''}">${title}</button>`).join('');
  }
  function menuOptions() {
    const list = [['home', 'Übersicht', true], ['time', 'Zeiterfassung', allowed('time')], ['orders', 'Arbeitsscheine', allowed('orders')], ['calendar', 'Kalender', allowed('calendar')], ['customers', 'Kunden', allowed('customers')], ['mailbox', 'Postfach', true], ['materials', 'Materialliste', isManager()], ['invoices', 'Abrechnungen Kunden', isManager()], ['settings', 'Einstellungen', true]];
    return list.filter(([, , visible]) => visible).map(([id, title]) => `<option value="${id}" ${state.view === id ? 'selected' : ''}>${title}</option>`).join('');
  }
  function selector() {
    if (!isManager()) return '';
    const businesses = isAdmin() ? `<label>Geschäftskonto<select data-select="business"><option value="">Geschäftskonto wählen</option>${businessList().map(person => `<option value="${person.id}" ${same(person.id, activeBusinessId()) ? 'selected' : ''}>${esc(person.company_name || person.username)}</option>`).join('')}</select></label>` : '';
    return `<div class="account-selector">${businesses}<label>Mitarbeiter<select data-select="employee">${employees().map(person => `<option value="${person.id}" ${same(person.id, currentEmployeeId()) ? 'selected' : ''}>${esc(person.username)}</option>`).join('')}</select></label></div>`;
  }
  function appView() {
    const brand = currentBusiness()?.company_name || 'Zeiterfassung';
    const menu = state.menuOpen ? `<section class="app-menu-sheet" aria-label="Menü"><header><b>Menü auswählen</b><button class="secondary small" data-action="toggle-menu">Schließen</button></header><nav>${navItems()}<hr><button data-action="logout">Abmelden</button></nav></section>` : '';
    return `<div class="app-shell"><header class="topbar"><div><span class="eyebrow">${esc(brand)}</span><h1>Zeiterfassung</h1></div><div class="top-actions">${selector()}<button class="menu-toggle" data-action="toggle-menu" aria-expanded="${state.menuOpen}">☰ Menü</button></div></header>${menu}<main class="content">${view()}${noticeView()}</main></div>`;
  }
  function view() { return ({ home: homeView, time: timeView, orders: ordersView, calendar: calendarView, customers: customersView, mailbox: mailboxView, materials: materialsView, invoices: invoicesView, settings: settingsView }[state.view] || homeView)(); }
  function dueHours(value) { const day = new Date(`${value}T12:00:00`).getDay(); return day === 5 ? 5 : day === 0 || day === 6 ? 0 : 8; }
  function dayRows(employee, date) { return state.rows.entries.filter(row => same(row.employee_id, employee) && row.work_date === date); }
  function dayHours(employee, date) { return dayRows(employee, date).reduce((sum, row) => sum + number(row.executed_hours), 0); }
  function currentVacation(employee, date) { return state.rows.vacations.find(row => same(row.employee_id, employee) && row.status === 'approved' && row.start_date <= date && row.end_date >= date); }
  function requestedVacation(employee, date) { return state.rows.vacations.find(row => same(row.employee_id, employee) && row.status === 'requested' && row.start_date <= date && row.end_date >= date); }
  function sickDay(employee, date) { return state.rows.days.find(row => same(row.employee_id, employee) && row.work_date === date && number(row.sick) > 0); }
  function locked(employee, date) { return Boolean(sickDay(employee, date) || currentVacation(employee, date)); }
  function selectedYear() { return String(state.date || today()).slice(0, 4); }
  function dateInYear(value, year = selectedYear()) { return String(value || '').startsWith(`${year}-`); }
  function vacationLeft(employee, year = selectedYear()) {
    const person = state.people.find(row => same(row.id, employee)) || state.profile;
    const used = state.rows.vacations
      .filter(row => same(row.employee_id, employee) && row.status === 'approved' && String(row.start_date || '') <= `${year}-12-31` && String(row.end_date || '') >= `${year}-01-01`)
      .reduce((sum, row) => sum + number(row.requested_days), 0);
    return Math.max(0, number(person?.vacation_allowance) - used);
  }
  function totalSick(employee, year = selectedYear()) { return state.rows.days.filter(row => same(row.employee_id, employee) && dateInYear(row.work_date, year) && number(row.sick) > 0).reduce((sum, row) => sum + number(row.sick), 0); }
  function annualOvertime(employee, year = selectedYear()) {
    const dailyHours = new Map();
    const linkedOrderIds = new Set();
    state.rows.entries.filter(row => same(row.employee_id, employee) && dateInYear(row.work_date, year)).forEach(row => {
      dailyHours.set(row.work_date, number(dailyHours.get(row.work_date)) + number(row.executed_hours));
      if (row.work_order_id) linkedOrderIds.add(String(row.work_order_id));
    });
    // Orders normally have a linked entry. Only add older orders that do not,
    // so an order never counts twice in the annual balance.
    state.rows.orders.filter(row => same(row.employee_id, employee) && dateInYear(row.work_date, year) && !linkedOrderIds.has(String(row.id))).forEach(row => {
      dailyHours.set(row.work_date, number(dailyHours.get(row.work_date)) + number(row.executed_hours));
    });
    return [...dailyHours.entries()].reduce((sum, [workDate, executed]) => sum + executed - dueHours(workDate), 0);
  }
  function homeView() {
    const employee = currentEmployeeId(); const year = selectedYear(); const performed = dayHours(employee, state.date); const hasWork = Boolean(dayRows(employee, state.date).length || state.rows.orders.some(row => same(row.employee_id, employee) && row.work_date === state.date)); const overtime = annualOvertime(employee, year);
    return `<section class="page-head"><div><span class="eyebrow">Willkommen, ${esc(selectedEmployee()?.username || '')}</span><h2>${dateLabel(state.date)}</h2></div><label class="date-field">Tag<input type="date" data-date value="${state.date}"></label></section><section class="stat-grid"><article><span>Überstunden ${year}</span><strong class="${overtime > 0 ? 'positive' : overtime < 0 ? 'negative' : ''}">${overtime ? hours(overtime) : '—'}</strong></article><article><span>Urlaub übrig ${year}</span><strong>${number(vacationLeft(employee, year)).toLocaleString('de-DE')} Tage</strong></article><article><span>Krankheitstage ${year}</span><strong>${number(totalSick(employee, year)).toLocaleString('de-DE')} Tage</strong></article></section><section class="panel"><h3>Heutige Arbeitszeit</h3><p>${locked(employee, state.date) ? (sickDay(employee, state.date) ? 'Krank gemeldet – keine Arbeitszeit möglich.' : 'Genehmigter Urlaub – keine Arbeitszeit möglich.') : hasWork ? `${hours(performed)} erfasst von ${hours(dueHours(state.date))} Sollzeit.` : 'Für diesen Tag wurde noch keine Arbeitszeit erfasst.'}</p><div class="actions"><button class="primary" data-action="nav" data-view="time">Zeiterfassung öffnen</button><button class="secondary" data-action="nav" data-view="orders">Arbeitsschein erstellen</button></div></section>`;
  }
  function timeOptions(name, value, sync) { return `<input name="${name}" type="time" step="900" value="${value || ''}" data-sync="${sync}">`; }
  function customerOptions() { return `<datalist id="customer-list">${state.rows.customers.map(row => `<option value="${esc(row.name)}"></option>`).join('')}</datalist>`; }
  function timeView() {
    const employee = currentEmployeeId(); const entries = dayRows(employee, state.date); const previous = entries.at(-1)?.end_time?.slice(0, 5) || '07:30';
    return `<section class="page-head"><div><span class="eyebrow">Zeiterfassung von ${esc(selectedEmployee()?.username || '')}</span><h2>${dateLabel(state.date)}</h2></div><label class="date-field">Tag<input type="date" data-date value="${state.date}"></label></section>${locked(employee, state.date) ? `<div class="locked">Für diesen Tag kann keine Zeiterfassung angelegt werden.</div>` : `<section class="panel"><h3>Arbeitszeit hinzufügen</h3><form id="time-form" class="entry-form"><label class="wide">Kunde<input name="customer" required list="customer-list" placeholder="Kundenname eingeben"></label><label>Arbeitsbeginn${timeOptions('start', previous, 'start')}</label><label>Arbeitsende${timeOptions('end', '', 'end')}</label><label>Pause in Stunden<input name="pause" type="number" min="0" step="0.25" value="0" data-sync="pause"></label><label>Ausgeführte Stunden<input name="hours" type="number" min="0.25" step="0.25" data-sync="hours"></label><button class="primary wide">Zeiterfassung speichern</button></form>${customerOptions()}</section>`}<section class="list-section"><h3>Einträge des Tages</h3>${entries.length ? entries.map(row => `<article class="row-card"><div><b>${esc(row.customer_name || 'Ohne Kunde')}</b><span>${time(row.start_time)} – ${time(row.end_time)} · ${hours(row.executed_hours)}</span></div><button class="danger small" data-action="delete-time" data-id="${row.id}">Löschen</button></article>`).join('') : '<p class="empty">Für diesen Tag liegen noch keine Einträge vor.</p>'}</section>`;
  }
  function materialRows() { return `<div class="material-row"><label>Material<input name="material" placeholder="Artikel eingeben"></label><label>Stückzahl<input name="quantity" type="number" min="0.25" step="0.25" value="1"></label></div>`; }
  function ordersView() {
    const employee = currentEmployeeId(); const dailyOrders = state.rows.orders.filter(row => same(row.employee_id, employee) && row.work_date === state.date); const allOrders = state.rows.orders.filter(row => same(row.employee_id, employee)); const showAll = isBusiness(); const orders = showAll ? allOrders : dailyOrders; const previous = dailyOrders.at(-1)?.end_time?.slice(0, 5) || dayRows(employee, state.date).at(-1)?.end_time?.slice(0, 5) || '07:30';
    return `<section class="page-head"><div><span class="eyebrow">Arbeitsscheine von ${esc(selectedEmployee()?.username || '')}</span><h2>${showAll ? 'Alle Arbeitsscheine' : `zu ${dateLabel(state.date)}`}</h2></div><label class="date-field">Tag<input type="date" data-date value="${state.date}"></label></section>${locked(employee, state.date) ? '<div class="locked">Für diesen Tag kann kein Arbeitsschein angelegt werden.</div>' : `<section class="panel"><h3>Neuer Arbeitsschein</h3><form id="order-form" class="entry-form"><label class="wide">Beschreibung<input name="title" required placeholder="Arbeitsauftrag beschreiben"></label><label class="wide">Kunde<input name="customer" required list="customer-list" placeholder="Kundenname eingeben"></label><label>Arbeitsbeginn${timeOptions('start', previous, 'start')}</label><label>Arbeitsende${timeOptions('end', '', 'end')}</label><label>Pause in Stunden<input name="pause" type="number" min="0" step="0.25" value="0" data-sync="pause"></label><label>Ausgeführte Stunden<input name="hours" type="number" min="0.25" step="0.25" data-sync="hours"></label><label class="wide">Dokumentation<textarea name="documentation" placeholder="Arbeitsablauf, Hinweise oder Besonderheiten"></textarea></label><label class="wide">Dokumente<input name="documents" type="file" multiple accept="image/*,.pdf,.doc,.docx,.xlsx"></label><div class="wide material-block"><h4>Material</h4><div id="material-inputs">${materialRows()}</div><button type="button" class="secondary small" data-action="more-material">Weiteres Material</button></div><button class="primary wide">Arbeitsschein bestätigen</button></form>${customerOptions()}</section>`}<section class="list-section"><h3>${showAll ? 'Alle Arbeitsscheine' : 'Arbeitsscheine des Tages'}</h3>${orders.length ? orders.map(order => orderCard(order, showAll)).join('') : `<p class="empty">${showAll ? 'Es liegen noch keine Arbeitsscheine vor.' : 'Für diesen Tag liegen noch keine Arbeitsscheine vor.'}</p>`}</section>`;
  }
  function orderCard(order, showDate = false) { const items = state.rows.orderItems.filter(row => same(row.work_order_id, order.id)); const docs = state.rows.documents.filter(row => same(row.work_order_id, order.id)); return `<article class="order-card"><header><div><b>${esc(order.customer_name || 'Ohne Kunde')}</b><span>${showDate ? `${dateLabel(order.work_date)} · ` : ''}${esc(order.title)} · ${time(order.start_time)} – ${time(order.end_time)} · ${hours(order.executed_hours)}</span></div><div><button class="secondary small" data-action="toggle-invoice" data-id="${order.id}" data-value="${order.invoiced ? 'false' : 'true'}">${order.invoiced ? 'Abgerechnet' : 'Nicht abgerechnet'}</button><button class="danger small" data-action="delete-order" data-id="${order.id}">Löschen</button></div></header>${order.documentation ? `<p>${esc(order.documentation)}</p>` : ''}${items.length ? `<p><b>Material:</b> ${items.map(item => `${esc(item.position_name)} (${number(item.quantity)})`).join(', ')}</p>` : ''}${docs.length ? `<div class="files">${docs.map(doc => `<button data-action="download-document" data-path="${esc(doc.file_path)}" data-name="${esc(doc.file_name)}">${esc(doc.file_name)}</button>`).join('')}</div>` : ''}</article>`; }
  function calendarView() {
    const employee = currentEmployeeId(); const [year, month] = state.month.split('-').map(Number); const first = new Date(year, month - 1, 1); const leading = (first.getDay() + 6) % 7; const days = new Date(year, month, 0).getDate();
    const cells = Array.from({ length: leading + days }, (_, index) => { if (index < leading) return '<div class="day empty-day"></div>'; const date = `${state.month}-${String(index - leading + 1).padStart(2, '0')}`; const sick = sickDay(employee, date); const approved = currentVacation(employee, date); const requested = requestedVacation(employee, date); const hasOrder = state.rows.orders.some(row => same(row.employee_id, employee) && row.work_date === date); return `<button class="day ${date === state.date ? 'selected' : ''} ${sick ? 'sick' : approved ? 'vacation' : requested ? 'requested' : ''}" data-action="pick-date" data-date="${date}"><b>${index - leading + 1}</b>${sick ? '<i>Krank</i>' : approved ? '<i>Urlaub</i>' : requested ? '<i>Antrag</i>' : hasOrder ? '<i>Arbeit</i>' : ''}</button>`; }).join('');
    const sick = sickDay(employee, state.date); const vacation = currentVacation(employee, state.date) || requestedVacation(employee, state.date); const dailyOrders = state.rows.orders.filter(row => same(row.employee_id, employee) && row.work_date === state.date);
    return `<section class="page-head"><div><span class="eyebrow">Kalender von ${esc(selectedEmployee()?.username || '')}</span><h2>${dateLabel(state.date)}</h2></div></section><section class="calendar-layout"><div class="panel"><div class="calendar-title"><button class="secondary small" data-action="month" data-direction="-1">‹</button><h3>${monthLabel(state.month)}</h3><button class="secondary small" data-action="month" data-direction="1">›</button></div><div class="weekdays"><span>Mo</span><span>Di</span><span>Mi</span><span>Do</span><span>Fr</span><span>Sa</span><span>So</span></div><div class="calendar-grid">${cells}</div></div><aside class="day-detail"><h3>${dateLabel(state.date)}</h3><p>Überstunden: ${locked(employee, state.date) ? '—' : hours(dayHours(employee, state.date) - dueHours(state.date))}</p><p>Urlaub übrig: ${number(vacationLeft(employee)).toLocaleString('de-DE')} Tage</p><p>Krankheitstage: ${number(totalSick(employee)).toLocaleString('de-DE')}</p>${sick ? '<div class="status sick-status">Krank gemeldet</div>' : ''}${vacation ? `<div class="status ${vacation.status === 'approved' ? 'vacation-status' : 'requested-status'}">${vacation.status === 'approved' ? 'Urlaub genehmigt' : 'Urlaub beantragt'}: ${dateLabel(vacation.start_date)} bis ${dateLabel(vacation.end_date)}</div>` : ''}<div class="actions">${(!sick && (isManager() || same(employee, state.profile.id))) ? '<button class="secondary" data-action="mark-sick">Krank melden</button>' : ''}${sick && isManager() ? '<button class="secondary" data-action="remove-sick">Krankheitstag entfernen</button>' : ''}${!sick && !currentVacation(employee, state.date) ? '<button class="primary" data-action="show-vacation">Urlaub beantragen</button>' : ''}</div>${state.view === 'calendar' && state.showVacation ? `<form id="vacation-form" class="compact-form"><label>Von<input name="start" type="date" value="${state.date}" required></label><label>Bis<input name="end" type="date" value="${state.date}" required></label><button class="primary">Antrag senden</button></form>` : ''}<h4>Durchgeführt</h4>${dailyOrders.length ? dailyOrders.map(order => `<p>${esc(order.customer_name)} · ${hours(order.executed_hours)}</p>`).join('') : '<p class="empty">Keine Arbeitsscheine an diesem Tag.</p>'}</aside></section>`;
  }
  function customerForm(customer = null) { const fields = customer?.custom_fields || {}; const input = (key, label) => `<label>${label}<input name="${key}" value="${esc(fields[key] || '')}"></label>`; return `<section class="panel"><h3>${customer ? 'Kunde bearbeiten' : 'Kunde hinzufügen'}</h3><form id="customer-form" class="entry-form"><input type="hidden" name="id" value="${esc(customer?.id || '')}"><label>Name<input name="name" required value="${esc(customer?.name || '')}"></label>${input('first_name', 'Vorname')}${input('street', 'Straße')}${input('house_no', 'Hausnummer')}${input('city', 'Ort')}${input('postal_code', 'Postleitzahl')}${input('phone_private', 'Tel. privat')}${input('phone_mobile', 'Tel. Mobil')}${input('email', 'E-Mail-Adresse')}<label class="wide">Zusätzliche Eingabefelder<textarea name="extra" placeholder="Beispiel: Ansprechpartner: Max Mustermann">${esc(Object.entries(fields).filter(([key]) => key.startsWith('extra_')).map(([, value]) => value).join('\n'))}</textarea></label><div class="actions wide">${customer ? `<button type="button" class="danger" data-action="delete-customer" data-id="${customer.id}">Kunde löschen</button>` : ''}<button class="primary">Kunde speichern</button></div></form></section>`; }
  function customersView() { const selected = state.rows.customers.find(row => same(row.id, state.selectedCustomerId)); return `<section class="page-head"><div><span class="eyebrow">Kunden</span><h2>Kundenliste</h2></div><button class="primary" data-action="new-customer">Kunde hinzufügen</button></section>${selected || state.newCustomer ? customerForm(selected) : ''}<section class="list-section">${state.rows.customers.length ? state.rows.customers.map(customer => `<button class="customer-card" data-action="select-customer" data-id="${customer.id}"><b>${esc(customer.name)}</b><span>${hours(state.rows.entries.filter(entry => same(entry.customer_id, customer.id)).reduce((sum, entry) => sum + number(entry.executed_hours), 0))} im Jahr</span></button>`).join('') : '<p class="empty">Noch keine Kunden angelegt.</p>'}</section>`; }
  function mailboxView() { const all = state.rows.messages; const filtered = all.filter(message => state.folder === 'trash' ? Boolean(message.deleted_at) : !message.deleted_at && (state.folder === 'read' ? Boolean(message.read_at) : state.folder === 'unread' ? !message.read_at : true)); return `<section class="page-head"><div><span class="eyebrow">Persönlich</span><h2>Postfach</h2></div></section><div class="folders">${[['all','Alle'],['unread','Ungelesen'],['read','Gelesen'],['trash','Papierkorb']].map(([id, label]) => `<button data-action="folder" data-folder="${id}" class="${state.folder === id ? 'active' : ''}">${label}</button>`).join('')}</div><section class="message-list">${filtered.length ? filtered.map(message => messageCard(message)).join('') : '<p class="empty">In diesem Ordner sind keine Nachrichten.</p>'}</section>`; }
  function messageCard(message) { const body = message.body || {}; const decision = message.message_type === 'vacation_request' && isManager() ? `<div class="actions"><button class="primary small" data-action="vacation-decision" data-id="${message.id}" data-request="${esc(body.request_id || '')}" data-decision="approved">Genehmigen</button><button class="secondary small" data-action="vacation-decision" data-id="${message.id}" data-request="${esc(body.request_id || '')}" data-decision="rejected">Ablehnen</button></div>` : ''; const payslip = body.payslip_path ? `<button class="secondary small" data-action="download-payslip" data-path="${esc(body.payslip_path)}" data-name="${esc(body.file_name || 'Lohnabrechnung')}">Datei herunterladen</button>` : ''; return `<article class="message ${message.read_at ? 'read' : 'unread'}"><header><b>${esc(message.title)}</b><time>${new Intl.DateTimeFormat('de-DE', { dateStyle: 'short', timeStyle: 'short' }).format(new Date(message.created_at))}</time></header><p>${esc(body.message || body.note || (body.start_date ? `${dateLabel(body.start_date)} bis ${dateLabel(body.end_date)}` : ''))}</p>${decision}${payslip}<div class="message-actions">${!message.read_at && !message.deleted_at ? `<button data-action="read-message" data-id="${message.id}">Als gelesen markieren</button>` : ''}${message.deleted_at ? `<button class="danger" data-action="destroy-message" data-id="${message.id}">Endgültig löschen</button>` : `<button data-action="trash-message" data-id="${message.id}">Löschen</button>`}</div></article>`; }
  function materialsView() { if (!isManager()) return '<div class="locked">Dieser Bereich ist nicht freigegeben.</div>'; return `<section class="page-head"><div><span class="eyebrow">Material</span><h2>Materialliste</h2></div></section><section class="panel"><form id="material-form" class="entry-form"><label>Artikel<input name="name" required></label><label>Preis in €<input name="price" type="number" min="0" step="0.01" value="0"></label><button class="primary">Material speichern</button></form></section><section class="list-section">${state.rows.materials.filter(row => row.active !== false).map(row => `<article class="row-card"><div><b>${esc(row.name)}</b><span>${number(row.unit_price).toLocaleString('de-DE', { style: 'currency', currency: 'EUR' })}</span></div><button class="danger small" data-action="delete-material" data-id="${row.id}">Löschen</button></article>`).join('') || '<p class="empty">Noch kein Material angelegt.</p>'}</section>`; }
  function invoicesView() { const orders = state.rows.orders.filter(order => same(order.employee_id, currentEmployeeId())); const grouped = Object.values(orders.filter(order => !order.invoiced).reduce((map, order) => { (map[order.customer_name || 'Ohne Kunde'] ||= []).push(order); return map; }, {})); return `<section class="page-head"><div><span class="eyebrow">Abrechnung</span><h2>Abrechnungen Kunden</h2></div></section>${grouped.length ? grouped.map(group => `<section class="panel"><h3>${esc(group[0].customer_name || 'Ohne Kunde')}</h3><p>${group.length} nicht abgerechnete Arbeitsscheine · ${hours(group.reduce((sum, order) => sum + number(order.executed_hours), 0))}</p><div class="actions">${group.map(order => `<button class="secondary small" data-action="toggle-invoice" data-id="${order.id}" data-value="true">${dateLabel(order.work_date)} abrechnen</button>`).join('')}</div></section>`).join('') : '<p class="empty">Alle Arbeitsscheine sind abgerechnet.</p>'}`; }
  function settingsView() {
    if (!isManager()) return `<section class="page-head"><div><span class="eyebrow">Mein Konto</span><h2>Einstellungen</h2></div></section><section class="panel"><p>Dein Konto und dein Passwort werden durch das Geschäftskonto verwaltet.</p><button class="secondary" data-action="pdf">Daten als PDF drucken</button></section>`;
    const target = selectedEmployee(); const business = currentBusiness(); const employeeEdit = target?.role === 'employee' ? `<section class="panel"><h3>Mitarbeiter bearbeiten: ${esc(target.username)}</h3><form id="employee-update-form" class="entry-form"><input type="hidden" name="id" value="${target.id}"><label>Benutzername<input name="username" value="${esc(target.username)}"></label><label>Neues Passwort<input name="password" type="password" minlength="8" placeholder="Nur bei Änderung"></label><label>Urlaubstage vorhanden<input name="allowance" type="number" min="0" step="0.5" value="${number(target.vacation_allowance)}"></label><div class="wide permissions">${[['time','Zeiterfassung'],['customers','Kunden'],['orders','Arbeitsscheine'],['calendar','Kalender']].map(([key, label]) => `<label><input type="checkbox" name="perm-${key}" ${target.menu_permissions?.[key] !== false ? 'checked' : ''}> ${label}</label>`).join('')}</div><div class="actions wide"><button type="button" class="danger" data-action="delete-employee" data-id="${target.id}">Mitarbeiter löschen</button><button class="primary">Speichern</button></div></form></section>` : '';
    const businessEdit = isAdmin() && business ? `<section class="panel"><h3>Geschäftskonto verwalten: ${esc(business.company_name || business.username)}</h3><form id="business-update-form" class="entry-form"><input type="hidden" name="id" value="${business.id}"><label>Firma<input name="company" value="${esc(business.company_name || '')}"></label><label>Benutzername<input name="username" value="${esc(business.username)}"></label><label>Neues Passwort<input name="password" type="password" minlength="8" placeholder="Nur bei Änderung"></label><div class="actions wide"><button type="button" class="danger" data-action="delete-business" data-id="${business.id}">Geschäftskonto löschen</button><button class="primary">Geschäftskonto speichern</button></div></form></section>` : '';
    return `<section class="page-head"><div><span class="eyebrow">Verwaltung</span><h2>Einstellungen</h2></div><button class="secondary" data-action="pdf">Daten als PDF drucken</button></section><section class="panel"><h3>Mein Benutzerkonto</h3><form id="self-form" class="entry-form"><label>Benutzername<input name="username" value="${esc(state.profile.username)}"></label><label>Neues Passwort<input name="password" type="password" minlength="8" placeholder="Nur bei Änderung"></label><label>Urlaubstage vorhanden<input name="allowance" type="number" min="0" step="0.5" value="${number(state.profile.vacation_allowance)}"></label>${isBusiness() ? `<label>Firma<input name="company" value="${esc(state.profile.company_name || '')}"></label>` : ''}<button class="primary">Konto speichern</button></form></section>${isAdmin() ? `<section class="panel"><h3>Neues Geschäftskonto</h3><form id="business-form" class="entry-form"><label>Firma<input name="company" required></label><label>Benutzername<input name="username" required></label><label>Passwort<input name="password" type="password" minlength="8" required></label><button class="primary">Geschäftskonto anlegen</button></form></section>` : ''}${businessEdit}<section class="panel"><h3>Mitarbeiter hinzufügen</h3>${activeBusinessId() ? `<form id="employee-form" class="entry-form"><label>Benutzername<input name="username" required></label><label>Passwort<input name="password" type="password" minlength="8" required></label><label>Urlaubstage vorhanden<input name="allowance" type="number" min="0" step="0.5" value="30"></label><div class="wide permissions">${[['time','Zeiterfassung'],['customers','Kunden'],['orders','Arbeitsscheine'],['calendar','Kalender']].map(([key, label]) => `<label><input type="checkbox" name="perm-${key}" checked> ${label}</label>`).join('')}</div><button class="primary wide">Mitarbeiter anlegen</button></form>` : '<p>Bitte zunächst ein Geschäftskonto auswählen.</p>'}</section>${activeBusinessId() ? `<section class="panel"><h3>Lohnabrechnung zustellen</h3><form id="payslip-form" class="entry-form"><label>Mitarbeiter<select name="employee">${employees().filter(person => person.role === 'employee').map(person => `<option value="${person.id}">${esc(person.username)}</option>`).join('')}</select></label><label class="wide">Datei<input name="file" type="file" accept=".pdf,image/*" required></label><button class="primary">In das Postfach zustellen</button></form></section>` : ''}${employeeEdit}`;
  }

  function roundTime(value) { if (!value) return ''; const [h, m] = value.split(':').map(Number); const rounded = Math.max(0, Math.min(23 * 60 + 45, Math.round((h * 60 + m) / 15) * 15)); return `${String(Math.floor(rounded / 60)).padStart(2, '0')}:${String(rounded % 60).padStart(2, '0')}`; }
  function syncTimes(form, source) { const start = form.elements.start, end = form.elements.end, pause = form.elements.pause, worked = form.elements.hours; if (!start || !end || !pause || !worked) return; start.value = roundTime(start.value); end.value = roundTime(end.value); const p = Math.max(0, Math.round(number(pause.value) * 4) / 4); pause.value = p; if (source === 'hours' && start.value && worked.value) { const total = Math.round(number(worked.value) * 4) / 4; worked.value = total; const [h, m] = start.value.split(':').map(Number); end.value = roundTime(`${String(Math.floor((h * 60 + m + (total + p) * 60) / 60) % 24).padStart(2, '0')}:${String((h * 60 + m + (total + p) * 60) % 60).padStart(2, '0')}`); } else if (start.value && end.value) { const [sh, sm] = start.value.split(':').map(Number); const [eh, em] = end.value.split(':').map(Number); const diff = Math.max(0, (eh * 60 + em - sh * 60 - p * 60) / 60); worked.value = Math.round(diff * 4) / 4; } }
  function times(form) { syncTimes(form, 'end'); const start = roundTime(form.elements.start.value); const end = roundTime(form.elements.end.value); const pause = Math.max(0, Math.round(number(form.elements.pause.value) * 4) / 4); const executed = Math.max(0, Math.round(number(form.elements.hours.value) * 4) / 4); if (!start || !end || executed <= 0) throw new Error('Bitte Arbeitsbeginn sowie Arbeitsende oder ausgeführte Stunden eingeben.'); return { start, end, pause, executed }; }
  async function ensureCustomer(name, employee) {
    const value = String(name || '').trim();
    if (!value) throw new Error('Bitte einen Kunden eingeben.');
    const exact = state.rows.customers.find(row => lower(row.name) === lower(value));
    if (exact) return exact;
    const similar = state.rows.customers.find(row => lower(row.name).includes(lower(value)) || lower(value).includes(lower(row.name)));
    if (similar && confirm(`Meinst du den vorhandenen Kunden „${similar.name}“?\nOK = vorhandenen Kunden verwenden · Abbrechen = neuen Kunden anlegen`)) return similar;
    try {
      const created = await write('customers', { employee_id: employee, name: value, custom_fields: {} });
      return created?.[0] || { id: null, name: value };
    } catch (error) {
      // It may already have been saved by another device or a previous request.
      const latest = await rows('customers', `select=*&employee_id=eq.${encodeURIComponent(employee)}&name=ilike.${encodeURIComponent(value)}`);
      const existing = (latest || []).find(row => lower(row.name) === lower(value));
      if (existing) return existing;
      throw error;
    }
  }
  async function ensureMaterial(name) {
    const value = String(name || '').trim();
    if (!value) return null;
    const exact = state.rows.materials.find(row => lower(row.name) === lower(value));
    if (exact) return exact;
    const similar = state.rows.materials.find(row => lower(row.name).includes(lower(value)) || lower(value).includes(lower(row.name)));
    if (similar && confirm(`Meinst du den vorhandenen Artikel „${similar.name}“?\nOK = vorhandenen Artikel verwenden · Abbrechen = neuen Artikel ohne Preis anlegen`)) return similar;
    try {
      const created = await write('materials', { business_id: activeBusinessId(), name: value, unit_price: 0, active: true });
      return created?.[0] || null;
    } catch (error) {
      const latest = await rows('materials', `select=*&name=ilike.${encodeURIComponent(value)}`);
      const existing = (latest || []).find(row => lower(row.name) === lower(value));
      if (existing) return existing;
      throw error;
    }
  }
  async function upload(bucket, path, file) { const response = await fetch(`${endpoint}/storage/v1/object/${bucket}/${path.split('/').map(encodeURIComponent).join('/')}`, { method: 'POST', headers: { apikey: publishableKey, Authorization: `Bearer ${state.session.access_token}`, 'Content-Type': file.type || 'application/octet-stream', 'x-upsert': 'false' }, body: file }); if (!response.ok) throw new Error('Die Datei konnte nicht hochgeladen werden.'); }
  async function download(bucket, path, name) { const response = await fetch(`${endpoint}/storage/v1/object/${bucket}/${path.split('/').map(encodeURIComponent).join('/')}`, { headers: { apikey: publishableKey, Authorization: `Bearer ${state.session.access_token}` } }); if (!response.ok) throw new Error('Die Datei konnte nicht heruntergeladen werden.'); const blob = await response.blob(); const link = document.createElement('a'); link.href = URL.createObjectURL(blob); link.download = name || 'Datei'; link.click(); setTimeout(() => URL.revokeObjectURL(link.href), 1000); }

  async function saveTime(form) { const employee = currentEmployeeId(); if (locked(employee, state.date)) throw new Error('Für diesen Tag darf keine Arbeitszeit erfasst werden.'); const customer = await ensureCustomer(form.elements.customer.value, employee); const value = times(form); await write('time_entries', { employee_id: employee, work_date: state.date, customer_id: customer.id, customer_name: customer.name, start_time: value.start, end_time: value.end, pause_hours: value.pause, executed_hours: value.executed, calculation_mode: 'end_time' }); }
  async function saveOrder(form) { const employee = currentEmployeeId(); if (locked(employee, state.date)) throw new Error('Für diesen Tag darf kein Arbeitsschein angelegt werden.'); const customer = await ensureCustomer(form.elements.customer.value, employee); const value = times(form); const created = await write('work_orders', { employee_id: employee, work_date: state.date, customer_id: customer.id, customer_name: customer.name, title: String(form.elements.title.value || '').trim(), start_time: value.start, end_time: value.end, pause_hours: value.pause, executed_hours: value.executed, calculation_mode: 'end_time', documentation: String(form.elements.documentation.value || '') }); const order = created?.[0]; if (!order) throw new Error('Der Arbeitsschein wurde nicht gespeichert.'); /* The database creates and synchronizes the linked time entry itself. Do not insert it a second time. */ const materialInputs = [...form.querySelectorAll('[name="material"]')]; const quantities = [...form.querySelectorAll('[name="quantity"]')]; for (let index = 0; index < materialInputs.length; index++) { const material = await ensureMaterial(materialInputs[index].value); if (material) await write('work_order_items', { work_order_id: order.id, position_name: material.name, quantity: Math.max(.25, number(quantities[index]?.value || 1)), unit_price: number(material.unit_price), material_id: material.id }); }
    for (const file of [...form.elements.documents.files]) { const safe = file.name.replace(/[^A-Za-z0-9._-]/g, '_'); const path = `${employee}/${order.id}-${Date.now()}-${safe}`; await upload('work-order-documents', path, file); await write('work_order_documents', { work_order_id: order.id, employee_id: employee, file_path: path, file_name: file.name, mime_type: file.type || null }); }
  }
  async function saveCustomer(form) { const id = String(form.elements.id.value || ''); const custom_fields = {}; ['first_name','street','house_no','city','postal_code','phone_private','phone_mobile','email'].forEach(key => { custom_fields[key] = String(form.elements[key].value || '').trim(); }); String(form.elements.extra.value || '').split('\n').map(value => value.trim()).filter(Boolean).forEach((value, index) => custom_fields[`extra_${index + 1}`] = value); const data = { name: String(form.elements.name.value || '').trim(), custom_fields }; if (!data.name) throw new Error('Bitte einen Kundennamen eingeben.'); if (id) await write('customers', data, 'PATCH', `id=eq.${encodeURIComponent(id)}`); else await write('customers', { ...data, employee_id: currentEmployeeId() }); state.selectedCustomerId = ''; state.newCustomer = false; }
  async function setSick(value) { const employee = currentEmployeeId(); if (!isManager() && !same(employee, state.profile.id)) throw new Error('Du darfst nur dich selbst krank melden.'); const row = state.rows.days.find(day => same(day.employee_id, employee) && day.work_date === state.date); if (value) await rest(`work_days?on_conflict=employee_id,work_date`, { method: 'POST', body: { employee_id: employee, work_date: state.date, sick: 1, vacation: number(row?.vacation) }, headers: { Prefer: 'resolution=merge-duplicates,return=representation' } }); else { if (!isManager()) throw new Error('Krankheitstage können nur durch den Chef entfernt werden.'); if (row) await rest(`work_days?employee_id=eq.${encodeURIComponent(employee)}&work_date=eq.${state.date}`, { method: 'DELETE' }); } }
  async function submitVacation(form) {
    const start = form.elements.start.value, end = form.elements.end.value;
    if (!start || !end) throw new Error('Bitte Start- und Enddatum eingeben.');
    const response = await functions('vacation-workflow', { action: 'request', startDate: start, endDate: end, employeeId: currentEmployeeId() });
    if (!response?.request?.id) throw new Error(response?.error || 'Der Urlaub konnte nicht gespeichert werden.');
    state.rows.vacations = [response.request, ...state.rows.vacations.filter(row => !same(row.id, response.request.id))];
    state.showVacation = false;
  }
  function permissions(form) { return Object.fromEntries(['time','customers','orders','calendar'].map(key => [key, form.elements[`perm-${key}`]?.checked !== false])); }
  async function accountAction(action, payload) { const response = await functions('account-management', { action, ...payload }); if (response?.error) throw new Error(response.error); return response; }
  function printPdf() { const person = selectedEmployee(); const employee = person?.id; const lines = state.rows.entries.filter(row => same(row.employee_id, employee)).map(row => `<tr><td>${dateLabel(row.work_date)}</td><td>${esc(row.customer_name)}</td><td>${hours(row.executed_hours)}</td><td>${hours(dayHours(employee, row.work_date) - dueHours(row.work_date))}</td></tr>`).join(''); const popup = window.open('', '_blank'); if (!popup) throw new Error('Bitte Pop-ups erlauben, um die PDF zu erstellen.'); popup.document.write(`<!doctype html><title>Zeiterfassung ${esc(person?.username)}</title><style>body{font:14px Arial;padding:24px}table{width:100%;border-collapse:collapse}td,th{padding:8px;border-bottom:1px solid #ddd;text-align:left}</style><h1>Zeiterfassung – ${esc(person?.username)}</h1><p>Stunden gesamt: ${hours(state.rows.entries.filter(row => same(row.employee_id, employee)).reduce((sum, row) => sum + number(row.executed_hours), 0))}<br>Urlaub übrig: ${number(vacationLeft(employee))} Tage<br>Krankheitstage: ${number(totalSick(employee))}</p><table><thead><tr><th>Datum</th><th>Kunde</th><th>Arbeitsstunden</th><th>Überstunden</th></tr></thead><tbody>${lines}</tbody></table><script>window.onload=()=>window.print()<\/script>`); popup.document.close(); }

  root.addEventListener('click', event => { const button = event.target.closest('[data-action]'); if (!button) return; const action = button.dataset.action; if (action === 'toggle-menu') { state.menuOpen = !state.menuOpen; render(); return; } if (action === 'nav') { state.view = button.dataset.view; state.showVacation = false; state.menuOpen = false; render(); return; } if (action === 'logout') return logout(); if (action === 'forgot') return run('Wenn ein Konto gefunden wurde, wurden die zuständigen Personen informiert.', async () => { const name = root.querySelector('[name="username"]')?.value || ''; await request('/functions/v1/request-password-help', { method: 'POST', body: { username: name } }); }); if (action === 'pick-date') { state.date = button.dataset.date; state.showVacation = false; render(); return; } if (action === 'month') { const cursor = new Date(`${state.month}-01T12:00:00`); cursor.setMonth(cursor.getMonth() + number(button.dataset.direction)); state.month = cursor.toISOString().slice(0, 7); render(); return; } if (action === 'show-vacation') { state.showVacation = true; render(); return; } if (action === 'mark-sick') return run('Krankheitstag wurde sofort eingetragen.', () => setSick(true)); if (action === 'remove-sick') return run('Krankheitstag wurde entfernt.', () => setSick(false)); if (action === 'more-material') { document.getElementById('material-inputs')?.insertAdjacentHTML('beforeend', materialRows()); return; } if (action === 'delete-time') return confirm('Zeiterfassung wirklich löschen?') && run('Zeiterfassung wurde sofort gelöscht.', () => rest(`time_entries?id=eq.${encodeURIComponent(button.dataset.id)}`, { method: 'DELETE' })); if (action === 'delete-order') return confirm('Arbeitsschein inklusive Zeiterfassung wirklich löschen?') && run('Arbeitsschein wurde sofort gelöscht.', async () => { const id = button.dataset.id; await rest(`time_entries?work_order_id=eq.${encodeURIComponent(id)}`, { method: 'DELETE' }); await rest(`work_order_items?work_order_id=eq.${encodeURIComponent(id)}`, { method: 'DELETE' }); await rest(`work_order_documents?work_order_id=eq.${encodeURIComponent(id)}`, { method: 'DELETE' }); await rest(`work_orders?id=eq.${encodeURIComponent(id)}`, { method: 'DELETE' }); }); if (action === 'toggle-invoice') return run('Abrechnungsstatus gespeichert.', () => write('work_orders', { invoiced: button.dataset.value === 'true' }, 'PATCH', `id=eq.${encodeURIComponent(button.dataset.id)}`)); if (action === 'new-customer') { state.newCustomer = true; state.selectedCustomerId = ''; render(); return; } if (action === 'select-customer') { state.selectedCustomerId = button.dataset.id; state.newCustomer = false; render(); return; } if (action === 'delete-customer') return confirm('Kunde wirklich löschen?') && run('Kunde wurde gelöscht.', () => rest(`customers?id=eq.${encodeURIComponent(button.dataset.id)}`, { method: 'DELETE' })); if (action === 'folder') { state.folder = button.dataset.folder; render(); return; } if (action === 'read-message') return run('Nachricht als gelesen markiert.', () => write('mailbox_messages', { read_at: new Date().toISOString() }, 'PATCH', `id=eq.${encodeURIComponent(button.dataset.id)}`)); if (action === 'trash-message') return run('Nachricht in den Papierkorb verschoben.', () => write('mailbox_messages', { deleted_at: new Date().toISOString() }, 'PATCH', `id=eq.${encodeURIComponent(button.dataset.id)}`)); if (action === 'destroy-message') return confirm('Nachricht endgültig löschen?') && run('Nachricht endgültig gelöscht.', () => rest(`mailbox_messages?id=eq.${encodeURIComponent(button.dataset.id)}`, { method: 'DELETE' })); if (action === 'vacation-decision') return run('Entscheidung wurde sofort übermittelt.', async () => { await functions('vacation-workflow', { action: 'decide', requestId: button.dataset.request, status: button.dataset.decision }); await write('mailbox_messages', { read_at: new Date().toISOString() }, 'PATCH', `id=eq.${encodeURIComponent(button.dataset.id)}`); }); if (action === 'delete-material') return confirm('Material wirklich löschen?') && run('Material wurde entfernt.', () => rest(`materials?id=eq.${encodeURIComponent(button.dataset.id)}`, { method: 'DELETE' })); if (action === 'download-document') return run('', () => download('work-order-documents', button.dataset.path, button.dataset.name)); if (action === 'download-payslip') return run('', () => download('employee-payslips', button.dataset.path, button.dataset.name)); if (action === 'delete-employee') return confirm('Mitarbeiterkonto wirklich löschen?') && run('Mitarbeiterkonto wurde gelöscht.', () => accountAction('employee-delete', { employeeId: button.dataset.id })); if (action === 'delete-business') return confirm('Geschäftskonto und alle zugehörigen Mitarbeiter wirklich löschen?') && run('Geschäftskonto wurde gelöscht.', () => accountAction('business-delete', { businessId: button.dataset.id })); if (action === 'pdf') return printPdf(); });
  root.addEventListener('change', event => { const target = event.target; if (target.matches('[data-date]')) { state.date = target.value || today(); state.month = state.date.slice(0, 7); render(); } if (target.matches('[data-select="business"]')) { state.businessId = target.value; state.employeeId = ''; localStorage.setItem('zeiterfassung-business-v700', state.businessId); render(); } if (target.matches('[data-select="employee"]')) { state.employeeId = target.value; localStorage.setItem('zeiterfassung-employee-v700', state.employeeId); render(); } if (target.matches('[data-select="view"]')) { state.view = target.value; state.showVacation = false; render(); } if (target.matches('[data-sync]')) syncTimes(target.form, target.dataset.sync); });
  root.addEventListener('input', event => { const target = event.target; if (target.matches('[data-sync]')) syncTimes(target.form, target.dataset.sync); });
  root.addEventListener('submit', event => { const form = event.target; if (!(form instanceof HTMLFormElement)) return; event.preventDefault(); const handlers = { 'login-form': () => login(form.elements.username.value, form.elements.password.value), 'time-form': () => saveTime(form), 'order-form': () => saveOrder(form), 'vacation-form': () => submitVacation(form), 'customer-form': () => saveCustomer(form), 'material-form': () => write('materials', { business_id: activeBusinessId(), name: String(form.elements.name.value || '').trim(), unit_price: number(form.elements.price.value), active: true }), 'business-form': () => accountAction('business-create', { companyName: form.elements.company.value, username: form.elements.username.value, password: form.elements.password.value }), 'business-update-form': () => accountAction('business-update', { businessId: form.elements.id.value, companyName: form.elements.company.value, username: form.elements.username.value, password: form.elements.password.value }), 'employee-form': () => accountAction('employee-create', { businessId: activeBusinessId(), username: form.elements.username.value, password: form.elements.password.value, vacationAllowance: number(form.elements.allowance.value), menuPermissions: permissions(form) }), 'employee-update-form': () => accountAction('employee-update', { employeeId: form.elements.id.value, username: form.elements.username.value, password: form.elements.password.value, vacationAllowance: number(form.elements.allowance.value), menuPermissions: permissions(form) }), 'self-form': () => accountAction('self-update', { username: form.elements.username.value, password: form.elements.password.value, companyName: form.elements.company?.value, vacationAllowance: number(form.elements.allowance.value) }), 'payslip-form': async () => { const file = form.elements.file.files?.[0]; const employee = String(form.elements.employee.value || ''); if (!file || !employee) throw new Error('Bitte Mitarbeiter und Datei auswählen.'); const path = `${activeBusinessId()}/${employee}/${Date.now()}-${file.name.replace(/[^A-Za-z0-9._-]/g, '_')}`; await upload('employee-payslips', path, file); await write('employee_payslips', { business_id: activeBusinessId(), employee_id: employee, uploaded_by: state.profile.id, file_path: path, file_name: file.name, mime_type: file.type || null }); await write('mailbox_messages', { recipient_id: employee, sender_id: state.profile.id, message_type: 'info', title: 'Neue Lohnabrechnung', body: { message: 'Eine neue Lohnabrechnung steht zum Herunterladen bereit.', payslip_path: path, file_name: file.name } }); } }; const handler = handlers[form.id]; if (handler) run(form.id === 'login-form' ? '' : 'Änderung wurde sofort gespeichert.', handler); });

  function render() { if (!endpoint || !publishableKey) { root.innerHTML = '<main class="login-page"><section class="login-card"><h1>Zeiterfassung</h1><p>Die App-Konfiguration fehlt.</p></section></main>'; return; } root.innerHTML = state.session && state.profile ? appView() : loginView(); }
  window.addEventListener('unhandledrejection', event => { event.preventDefault(); announce('Etwas ist schiefgelaufen. Bitte die Seite neu laden.', true); });
  try { state.session = safeJson(localStorage.getItem(storageKey)); if (state.session?.access_token) loadApplication(); else render(); } catch { render(); }
})();

